patch:
diff --git a/recreate-no-var-check.js b/recreate-no-var-check.js
new file mode 100644
index 0000000..1e538a3
--- /dev/null
+++ b/recreate-no-var-check.js
@@ -0,0 +1,77 @@
+/**
+ * Check for the `no-var` autofix bug: the fixed code must not throw a
+ * ReferenceError when it is run.
+ *
+ * Usage (from the repo root):
+ *   node recreate-no-var-check.js            # check this checkout
+ *   node recreate-no-var-check.js 9.37.0     # check a published eslint release
+ *
+ * Exit code: 0 = fixed code runs fine, 1 = fixed code throws ReferenceError
+ * (bug present), 2 = the check itself could not run.
+ */
+"use strict";
+
+const fs = require("node:fs");
+const os = require("node:os");
+const path = require("node:path");
+const { execFileSync } = require("node:child_process");
+const { pathToFileURL } = require("node:url");
+
+const SOURCE = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+function loadLinter(version) {
+	if (!version) {
+		return require("./lib/api").Linter;
+	}
+	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "no-var-eslint-"));
+
+	fs.writeFileSync(path.join(dir, "package.json"), "{}");
+	execFileSync("npm", ["install", "--no-audit", "--no-fund", `eslint@${version}`], {
+		cwd: dir,
+		stdio: "ignore",
+	});
+	return require(path.join(dir, "node_modules", "eslint")).Linter;
+}
+
+async function callA(code, label) {
+	const dir = fs.mkdtempSync(path.join(os.tmpdir(), "no-var-run-"));
+	const file = path.join(dir, `${label}.mjs`);
+	const log = console.log;
+
+	fs.writeFileSync(file, code);
+	console.log = () => {};
+	try {
+		await (await import(pathToFileURL(file).href)).a();
+	} finally {
+		console.log = log;
+	}
+}
+
+(async () => {
+	const Linter = loadLinter(process.argv[2]);
+	const linter = new Linter();
+	const { output } = linter.verifyAndFix(SOURCE, [
+		{ rules: { "no-var": "error" } },
+	]);
+
+	console.log(`--- code after --fix ---\n${output}`);
+
+	await callA(SOURCE, "original"); // sanity: the original code runs fine
+
+	try {
+		await callA(output, "fixed");
+	} catch (error) {
+		console.log(`fixed code threw: ${error.name}: ${error.message}`);
+		process.exitCode = error instanceof ReferenceError ? 1 : 2;
+		return;
+	}
+	console.log("fixed code ran without throwing");
+})().catch(error => {
+	console.error(error);
+	process.exitCode = 2;
+});
